package e.e.a;import android.preference.*;public class SettingsIntegrityTest{static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static PreferenceGroup group(PreferenceActivity a,String k){PreferenceGroup g=new PreferenceGroup(a);g.setKey(k);a.getPreferenceScreen().addPreference(g);return g;}static Preference add(PreferenceActivity a,PreferenceGroup g,String k){Preference p=new Preference(a);p.setKey(k);g.addPreference(p);return p;}public static void main(String[] args){check(!CachePlaybackPolicy.acquire("0"),"streaming must not acquire");check(CachePlaybackPolicy.acquire("1"),"cache mode must acquire");check(!CachePlaybackPolicy.acquire(null)&&!CachePlaybackPolicy.acquire("2"),"invalid mode must not acquire");PreferenceActivity a=new PreferenceActivity();PreferenceGroup general=group(a,"setting_whole"),comments=group(a,"comment"),about=group(a,"about");add(a,general,"remove_ad_option");PreferenceGroup player=group(a,"player");add(a,player,"comment_size_percent");add(a,comments,"comment_opacity_percent");add(a,player,"comment_rows");add(a,comments,"share_ng_level");PreferenceGroup labs=group(a,"labs");add(a,labs,"labs_cashe_speed_up");PreferenceManager.values.put("play_mode","1");SettingsIntegrity.ensure(a);check(a.findPreference("app_theme")!=null,"theme restored without old anchor");check(a.findPreference("app_theme").click!=null,"theme actionable");ListPreference mode=(ListPreference)a.findPreference("play_mode");check(mode.getValue().equals("1"),"existing cache selection retained");check(mode.values[0].equals("0")&&mode.values[1].equals("1"),"native mode values retained");check(mode.change.onPreferenceChange(mode,"0")&&mode.getValue().equals("0"),"streaming selectable");check(!mode.change.onPreferenceChange(mode,"9"),"invalid values rejected");check(a.findPreference("comment_fetch_limit")!=null&&comments.entries.contains(a.findPreference("comment_fetch_limit")),"comment count restored in comment category");check(a.findPreference("comment_fetch_limit").click!=null,"comment count actionable");check(a.findPreference("remove_ad_option")==null&&a.findPreference("labs")==null,"removed controls cannot return");Preference version=PatchInfo.ensure(a,"v1.8.6-dev.1");check(about.entries.contains(version)&&version.getSummary().equals("v1.8.6-dev.1"),"version restored and current");check(a.findPreference("google_cast_connect").intent.target.endsWith("NicoidChromecastReceiverSelect"),"Cast connection remains actionable");check(a.findPreference("google_cast_disconnect").click!=null,"Cast disconnect remains actionable");check(comments.entries.contains(a.findPreference("comment_size_percent")),"comment controls are moved out of player");check(a.findPreference("comment_fetch_limit").getOrder()<a.findPreference("comment_opacity_percent").getOrder(),"acquisition precedes display settings");check(a.findPreference("comment_opacity_percent").getOrder()<a.findPreference("comment_size_percent").getOrder(),"opacity precedes size");check(a.findPreference("comment_size_percent").getOrder()<a.findPreference("comment_rows").getOrder()&&a.findPreference("comment_rows").getOrder()<a.findPreference("share_ng_level").getOrder(),"layout precedes NG sharing");check(a.findPreference("play_mode").getSummary().toString().contains("："),"playback summary explains current selection");check(a.findPreference("comment_fetch_limit").getSummary().toString().contains("："),"comment summary explains current selection");int count=general.entries.size();SettingsIntegrity.ensure(a);check(count==general.entries.size(),"setup idempotent");PreferenceActivity old=new PreferenceActivity();PreferenceGroup g=group(old,"setting_whole");Preference legacy=add(old,g,"material_you_mode");legacy.setOrder(4);ThemeChoice.settings(old);check(old.findPreference("material_you_mode")==null&&old.findPreference("app_theme").getOrder()==-1000,"old theme replaced at original position");PreferenceActivity flat=new PreferenceActivity();SettingsIntegrity.ensure(flat);check(flat.findPreference("app_theme")!=null&&flat.findPreference("play_mode")!=null&&flat.findPreference("comment_fetch_limit")!=null,"fallback without category anchors");check(SettingsIntegrity.noFinalStop("前半。後半。").equals("前半。後半"),"only final Japanese stop removed");check(SettingsIntegrity.noFinalStop("First. Last.").equals("First. Last"),"internal punctuation remains");check(!a.findPreference("play_mode").getSummary().toString().endsWith("。")&&!a.findPreference("comment_fetch_limit").getSummary().toString().endsWith("。"),"dynamic summaries omit final punctuation");System.out.println("Settings integrity: "+checks+" runtime checks passed");}}
